import React, { useState, useRef, useEffect, useId, useCallback } from 'react';
import { ChevronDown, Check, Search } from 'lucide-react';

/**
 * ASL ModePicker 独立组件 (契约交付 - 零 Tailwind 纯语义样式)
 * @param {Array<{ id: string, title: string, desc?: string }>} modes
 * @param {string} value - 当前选中的 mode id
 * @param {function(string): void} onChange - 选中变更回调
 */
export default function ModePicker({ modes = [], value, onChange }) {
  const [isOpen, setIsOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [highlightIndex, setHighlightIndex] = useState(0);

  const containerRef = useRef(null);
  const triggerRef = useRef(null);
  const searchInputRef = useRef(null);
  const listboxId = useId();

  const filteredModes = modes.filter((m) =>
    m.title.toLowerCase().includes(search.toLowerCase())
  );

  const currentMode = modes.find((m) => m.id === value) || modes[0];

  useEffect(() => {
    if (isOpen) {
      setSearch('');
      setHighlightIndex(0);
      const timer = setTimeout(() => searchInputRef.current?.focus(), 50);
      return () => clearTimeout(timer);
    }
  }, [isOpen]);

  const handleClose = useCallback((returnFocus = true) => {
    setIsOpen(false);
    if (returnFocus) {
      triggerRef.current?.focus();
    }
  }, []);

  // 外部点击关闭但不抢夺外部新目标焦点
  useEffect(() => {
    function handleClickOutside(event) {
      if (containerRef.current && !containerRef.current.contains(event.target)) {
        setIsOpen(false);
      }
    }
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleKeyDown = (e) => {
    if (!isOpen) {
      if (e.key === 'Enter' || e.key === ' ' || e.key === 'ArrowDown') {
        e.preventDefault();
        setIsOpen(true);
      }
      return;
    }

    if (e.key === 'Escape') {
      e.preventDefault();
      handleClose(true);
    } else if (e.key === 'Tab') {
      handleClose(false);
    } else if (e.key === 'ArrowDown') {
      e.preventDefault();
      setHighlightIndex((prev) => (prev + 1) % (filteredModes.length || 1));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setHighlightIndex((prev) => (prev - 1 + filteredModes.length) % (filteredModes.length || 1));
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (filteredModes[highlightIndex]) {
        onChange?.(filteredModes[highlightIndex].id);
        handleClose(true);
      }
    }
  };

  const activeOptionId = filteredModes[highlightIndex]
    ? `${listboxId}-opt-${filteredModes[highlightIndex].id}`
    : undefined;

  return (
    <div
      className="asl-mode-picker"
      ref={containerRef}
      onKeyDown={handleKeyDown}
    >
      <button
        ref={triggerRef}
        type="button"
        className="asl-mode-trigger"
        aria-label="当前 Mode"
        aria-haspopup="listbox"
        aria-expanded={isOpen}
        aria-controls={listboxId}
        onClick={() => setIsOpen((prev) => !prev)}
      >
        <span className="mode-label-prefix">当前 Mode:</span>
        <span className="mode-current-text">{currentMode?.title || '选择 Mode'}</span>
        <ChevronDown size={14} style={{ color: 'var(--ink-soft)' }} />
      </button>

      {isOpen && (
        <div
          id={listboxId}
          className="asl-mode-dropdown"
          role="listbox"
          tabIndex={-1}
        >
          <div className="asl-mode-search-box">
            <Search size={14} style={{ color: 'var(--ink-soft)' }} />
            <input
              ref={searchInputRef}
              type="text"
              placeholder="搜索可用 Mode..."
              value={search}
              aria-autocomplete="list"
              aria-controls={listboxId}
              aria-activedescendant={activeOptionId}
              onChange={(e) => {
                setSearch(e.target.value);
                setHighlightIndex(0);
              }}
            />
          </div>

          <ul className="asl-mode-list">
            {filteredModes.length === 0 ? (
              <li style={{ padding: '8px 10px', fontSize: '11px', color: 'var(--muted)' }}>
                未找到匹配的 Mode
              </li>
            ) : (
              filteredModes.map((mode, index) => {
                const isSelected = mode.id === value;
                const isHighlighted = index === highlightIndex;
                const optionId = `${listboxId}-opt-${mode.id}`;

                let itemClass = 'asl-mode-item';
                if (isHighlighted) itemClass += ' is-active';
                if (isSelected) itemClass += ' is-selected';

                return (
                  <li
                    id={optionId}
                    key={mode.id}
                    role="option"
                    aria-selected={isSelected}
                    className={itemClass}
                    onClick={() => {
                      onChange?.(mode.id);
                      handleClose(true);
                    }}
                    onMouseEnter={() => setHighlightIndex(index)}
                  >
                    <span>{mode.title}</span>
                    {isSelected && <Check size={14} style={{ color: 'var(--brand)' }} />}
                  </li>
                );
              })
            )}
          </ul>
        </div>
      )}
    </div>
  );
}
